content.text:
{
  "name": "Amptek 多道分析器",
  "name_en": "Amptek Multi-Channel Analyzer",
  "manufacturer": "Amptek",
  "description": "一种用于辐射探测器读出的多道分析器，可采集脉冲高度/能量谱并读取死时间和SCA计数。常用于X射线或其他辐射能谱测量、计数实验与探测器表征。",
  "description_en": "A multi-channel analyzer used with radiation detectors to acquire pulse-height/energy spectra and read dead time and SCA counters. It is commonly used for X-ray or other radiation spectroscopy, counting experiments, and detector characterization.",
  "actions": [
    {
      "action_name": "auto-closeConnection",
      "description": "关闭与多道分析器的网络连接。",
      "description_en": "Close the network connection to the multi-channel analyzer."
    },
    {
      "action_name": "auto-getDeadTime",
      "description": "获取死时间。",
      "description_en": "Get the dead time."
    },
    {
      "action_name": "auto-getMcaIP",
      "description": "获取MCA的IP地址。",
      "description_en": "Get the MCA IP address."
    },
    {
      "action_name": "auto-getMcaPort",
      "description": "获取MCA的通信端口。",
      "description_en": "Get the MCA communication port."
    },
    {
      "action_name": "auto-getScaCounters",
      "description": "读取SCA计数器数值。",
      "description_en": "Read the SCA counter values."
    },
    {
      "action_name": "auto-getSpectrum",
      "description": "采集并读取能谱数据。",
      "description_en": "Acquire and read the energy spectrum."
    },
    {
      "action_name": "auto-getStatus",
      "description": "获取设备状态。",
      "description_en": "Get the device status."
    },
    {
      "action_name": "auto-getValue",
      "description": "读取指定道址的计数值。",
      "description_en": "Read the count value of a specified channel."
    },
    {
      "action_name": "auto-openConnection",
      "description": "打开与多道分析器的网络连接。",
      "description_en": "Open a network connection to the multi-channel analyzer."
    },
    {
      "action_name": "auto-startCount",
      "description": "开始计数采集。",
      "description_en": "Start counting acquisition."
    },
    {
      "action_name": "auto-setPresetValue",
      "description": "设置预置计数值。",
      "description_en": "Set the preset count value."
    },
    {
      "action_name": "auto-setCountTime",
      "description": "设置计数时间。",
      "description_en": "Set the count time."
    },
    {
      "action_name": "auto-getCountTime",
      "description": "获取计数时间。",
      "description_en": "Get the count time."
    },
    {
      "action_name": "auto-stopCount",
      "description": "停止计数采集。",
      "description_en": "Stop counting acquisition."
    },
    {
      "action_name": "auto-canMonitor",
      "description": "获取是否支持监测。",
      "description_en": "Get whether monitoring is supported."
    },
    {
      "action_name": "auto-canStopCount",
      "description": "获取是否支持停止计数。",
      "description_en": "Get whether stopping the count is supported."
    },
    {
      "action_name": "auto-isCounting",
      "description": "获取是否正在计数。",
      "description_en": "Get whether counting is in progress."
    },
    {
      "action_name": "auto-wait",
      "description": "等待计数完成。",
      "description_en": "Wait for counting to complete."
    }
  ],
  "tag_hints": [
    "multi-channel analyzer",
    "radiation spectroscopy",
    "pulse-height spectrum",
    "dead time measurement",
    "SCA counters",
    "X-ray detection electronics"
  ]
}

